const ids = ["1:25","1:28","1:33","1:43","2:47","2:5","2:6","2:7","2:8","2:9","2:10","2:2","2:3","2:4","2:44","2:45","2:46","2:11","2:12","2:13","2:14","2:15","2:16","2:17","2:18","2:19","2:20","2:21","2:22","2:23","2:24","2:25","2:26","2:27","2:28","2:29","2:30","2:31","2:32","2:33","2:34","2:35","2:36","2:37","2:38","2:39","2:40","2:41","2:42","2:43"];
const out = [];
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) { out.push({id, missing:true}); continue; }
  const info = {id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  if (n.type === "COMPONENT" || n.type === "FRAME" || n.type === "INSTANCE") {
    info.children = n.children ? n.children.map(c => ({name:c.name, type:c.type, w:Math.round(c.width), h:Math.round(c.height), fills: c.fills && c.fills !== figma.mixed ? c.fills.map(f=>f.type) : null})) : [];
  }
  out.push(info);
}
// workspace page check
const pages = figma.root.children.map(p=>({id:p.id,name:p.name,childCount:p.children.length}));
return JSON.stringify({pages, out}, null, 1);

