function mkFrame(name,x,h=812){const f=figma.createFrame();f.name=name;f.resize(375,h);f.x=x;f.y=0;f.fills=solid(C.white);f.clipsContent=true;page.appendChild(f);return f;}
async function icon(compId,parent,x,y,color,size){const inst=(await G(compId)).createInstance();parent.appendChild(inst);inst.x=x;inst.y=y;if(size)inst.resize(size,size);if(color){for(const v of inst.findAll(n=>n.type==="VECTOR"||n.type==="ELLIPSE"||n.type==="LINE")){try{if(v.fills&&v.fills!==figma.mixed&&v.fills.length&&v.fills[0].type==="SOLID")v.fills=solid(color);}catch(e){}try{if(v.strokes&&v.strokes.length&&v.strokes[0].type==="SOLID")v.strokes=solid(color);}catch(e){}}}return inst;}
async function setT(t,s){if(t.fontName===figma.mixed){const rn=t.getRangeAllFontNames(0,t.characters.length);for(const fn of rn)await figma.loadFontAsync(fn);}else await figma.loadFontAsync(t.fontName);t.characters=s;}
