let count=0;const errs=[];
async function link(nodeId,destName){
 try{
  const n=await figma.getNodeByIdAsync(nodeId);
  if(!n){errs.push(nodeId);return;}
  const dest=F[destName];
  if(!dest){errs.push("dest "+destName);return;}
  const reaction={trigger:{type:"ON_CLICK"},actions:[{type:"NODE",destinationId:dest,navigation:"NAVIGATE",transition:{type:"DISSOLVE",duration:0.25,easing:{type:"EASE_IN_AND_EASE_OUT"}},resetVideoPosition:false,resetScrollPosition:false,preserveScrollPosition:false}]};
  n.reactions=[reaction];
  count++;
 }catch(e){errs.push(nodeId+" "+String(e.message).slice(0,60));}
}
