const page = figma.root.children.find(p=>p.id==="6:2");
const frames = page.children.filter(n=>n.type==="FRAME"&&/^\d\d_/.test(n.name)).map(f=>({name:f.name,w:Math.round(f.width),h:Math.round(f.height),reactions:f.findAll(n=>n.reactions&&n.reactions.length>0).length}));
const comps = page.children.filter(n=>n.type==="COMPONENT").length;
const otherPages = figma.root.children.map(p=>p.name+"("+p.children.length+")");
return JSON.stringify({frameCount:frames.length,comps,frames,otherPages});
